import 'dart:async';
import 'dart:isolate';

Future<void> main() async {
  final qabul = ReceivePort();
  final isolate = await Isolate.spawn(ishchi, qabul.sendPort);
  late StreamSubscription sub;
  sub = qabul.listen((xabar) {
    if (xabar is SendPort) {
      xabar.send('salom');
      return;
    }
    print(xabar);
    if (xabar == 'ishchi: salom') {
      sub.cancel();
      qabul.close();
      isolate.kill();
    }
  }, onDone: () {
    print('yakun');
  });
}

void ishchi(SendPort ota) {
  final qabul = ReceivePort();
  ota.send(qabul.sendPort);
  qabul.listen((xabar) {
    ota.send('ishchi: $xabar');
  });
}

