import 'dart:isolate';

Future<void> main() async {
  final chegara = 50;
  final tub = await Isolate.run(() {
    final topildi = <int>[];
    for (var n = 2; n <= chegara; n++) {
      var tubmi = true;
      for (var d = 2; d * d <= n; d++) {
        if (n % d == 0) {
          tubmi = false;
          break;
        }
      }
      if (tubmi) topildi.add(n);
    }
    return topildi;
  });
  print('tub sonlar: $tub');
  print('soni: ${tub.length}');
}

import 'package:flutter/foundation.dart';

int fibonacci(int n) {
  if (n < 2) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

