import 'package:flutter/foundation.dart';

int yigindi(Map<String, int> data) => data['a']! + data['b']!;

int bolish(Map<String, int> data) {
  final b = data['b']!;
  if (b == 0) throw ArgumentError('bolish nolga ruxsat etilmaydi');
  return data['a']! ~/ b;
}

Future<void> main() async {
  final natija = await compute(yigindi, {'a': 12, 'b': 30});
  debugPrint('yigindi: $natija');
  try {
    await compute(bolish, {'a': 10, 'b': 0});
  } catch (e) {
    debugPrint('xato: $e');
  }
}

