import 'dart:async';

class Navbat {
  Future<void> _oxirgi = Future.value();

  Future<T> qosh<T>(Future<T> Function() ish) {
    final keyingi = _oxirgi.then((_) => ish());
    _oxirgi = keyingi.then((_) {}, onError: (_) {});
    return keyingi;
  }
}

Future<void> main() async {
  final navbat = Navbat();
  navbat.qosh(() async {
    await Future<void>.delayed(const Duration(milliseconds: 20));
    print('1-tugadi');
  });
  navbat.qosh(() async {
    await Future<void>.delayed(const Duration(milliseconds: 5));
    print('2-tugadi');
  });
  await navbat.qosh(() async => print('3-tugadi'));
}
